import {nearestParcel,typeNames} from './city.js';
export const costs={home:100,market:120,farm:110,park:80,clinic:180,library:160,work:120,shelter:140,forest:45,pond:60,empty:10,'close-road':20,'open-road':10,hazard:0};
export const missions=[
 {id:'belong',mode:'city',title:'A Place to Belong',tag:'COZY · FIRST CHALLENGE',description:'Meet your neighbors, make a new gathering place, and let friendships find it.',grant:300,objectives:['Inspect 3 different citizens','Build a new neighborhood park','See 5 positive social experiences at your new park'],hint:'Choose an empty lot near homes. Citizens will decide to visit when they want company. Try 5× speed.'},
 {id:'garden',mode:'city',title:'The Learning Garden',tag:'COZY · DISCOVERY',description:'Create places for curiosity and connection, then watch citizens learn.',grant:380,objectives:['Build a new learning center','Build a new neighborhood park','See 5 positive learning experiences at your new center'],hint:'A nearby learning center shortens the journey. Curious citizens visit on their own; 5× or 20× lets the story unfold.'},
 {id:'storm',mode:'chaos',title:'Stormwatch',tag:'SURVIVAL · TIMED',description:'A storm is approaching. Prepare shelter and healthcare, then help the city weather it.',grant:500,objectives:['Build a storm shelter','Build a health clinic','Finish the storm with ≥95% survivors and ≥80% average health'],hint:'Preparation lasts 900 simulation ticks. The storm ends at tick 3,600. Build near homes before speeding up.',limit:3600,warning:900}
];
export function gameState(sim){sim.game??={mode:'city',visited:false,medals:{},run:null};return sim.game}
export function startMission(sim,id){const g=gameState(sim);if(g.run?.status==='active')return {ok:false,message:'Finish this challenge or return to free play first.'};const m=missions.find(m=>m.id===id);if(!m)return {ok:false,message:'Unknown challenge.'};g.mode=m.mode;g.visited=true;g.run={id,status:'active',started:sim.tick,grant:m.grant,spent:0,initialPopulation:sim.citizens.length,initialIds:sim.citizens.map(c=>c.id),inspected:[],builds:[],visits:0,seen:Object.fromEntries(sim.citizens.map(c=>[c.id,c.brain?.updates||0])),undoCosts:[],stormStarted:false,notified:false};sim.event(`Challenge started: ${m.title}. A construction grant of ${m.grant} is available.`);return {ok:true,message:`${m.title} started. Your citizens and memories are preserved.`}}
export function inspectCitizen(sim,id){const r=gameState(sim).run;if(r?.status==='active'&&!r.inspected.includes(id))r.inspected.push(id)}
export function remaining(sim){const r=gameState(sim).run;return r?.status==='active'?r.grant-r.spent:Infinity}
export function build(sim,tool,x,z){const r=gameState(sim).run;let price=0,p=nearestParcel(sim.world,x,z),resolved=tool==='restore'?p.original:tool;
 if(r?.status==='active'){if(tool==='hazard')return {ok:false,message:'Manual hazards are for free experiments. This challenge has its own conditions.'};if(!tool.includes('road')&&p.type===resolved)return {ok:false,message:'That lot already has this type of facility.'};price=costs[resolved]??0;if(price>remaining(sim))return {ok:false,message:`This costs ${price} grant coins; only ${remaining(sim)} remain.`}}
 const before={...p};sim.edit(tool,x,z);if(r?.status==='active'){r.spent+=price;r.undoCosts.push({price,worldHistory:sim.world.history.length,beforeBuilds:JSON.parse(JSON.stringify(r.builds)),revision:sim.world.revision});if(!tool.includes('road')&&tool!=='hazard'){r.builds=r.builds.filter(b=>b.id!==p.id);if(p.type!==before.type&&p.type!=='empty')r.builds.push({id:p.id,type:p.type});}r.undoCosts=r.undoCosts.slice(-30)}return {ok:true,message:sim.events[0].text}}
export function undoBuild(sim){const r=gameState(sim).run;if(r?.status==='active'){const last=r.undoCosts.at(-1);if(!last||last.revision!==sim.world.revision)return {ok:false,message:'Only your latest challenge construction can be undone.'};if(sim.undo()){r.undoCosts.pop();r.spent-=last.price;r.builds=last.beforeBuilds;if(r.undoCosts.length)r.undoCosts.at(-1).revision=sim.world.revision;return {ok:true,message:`Edit undone. ${last.price} grant coins returned.`}}return {ok:false,message:'Nothing to undo.'}}return {ok:sim.undo(),message:'Last environmental edit restored.'}}
export function goals(sim){const r=gameState(sim).run;if(!r)return [];const has=type=>r.builds.some(b=>b.type===type&&sim.world.parcels.find(p=>p.id===b.id)?.type===type);const health=sim.citizens.reduce((s,c)=>s+c.health,0)/Math.max(1,sim.citizens.length),survivors=sim.citizens.filter(c=>(r.initialIds||sim.citizens.map(c=>c.id)).includes(c.id)).length/Math.max(1,r.initialPopulation);if(r.id==='belong')return [{value:r.inspected.length,target:3},{value:has('park')?1:0,target:1},{value:r.visits,target:5}];if(r.id==='garden')return [{value:has('library')?1:0,target:1},{value:has('park')?1:0,target:1},{value:r.visits,target:5}];return [{value:has('shelter')?1:0,target:1},{value:has('clinic')?1:0,target:1},{value:sim.tick-r.started>=3600&&survivors>=.95&&health>=80?1:0,target:1}]}
export function challengeStep(sim){const g=gameState(sim),r=g.run;if(r?.status!=='active')return;const m=missions.find(m=>m.id===r.id),elapsed=sim.tick-r.started;
 for(const c of [...sim.citizens,...sim.archived]){const current=c.brain?.updates||0,previous=r.seen[c.id]??0;if(current>previous){for(const e of (c.brain?.episodes||[]).slice(0,current-previous)){const required=r.id==='belong'?'Socializing':'Learning';if(e.reward>0&&e.action===required&&r.builds.some(b=>b.id===e.placeId&&b.type===(r.id==='belong'?'park':'library')))r.visits++}r.seen[c.id]=current}}
 if(m.id==='storm'&&elapsed>=m.warning&&!r.stormStarted){r.stormStarted=true;sim.catalyst('Storm');sim.event('Stormwatch: the storm has arrived. Citizens choose how to respond.');}
 const complete=goals(sim).every(o=>o.value>=o.target);let failure=sim.citizens.length===0||(m.limit&&elapsed>=m.limit&&!complete);
 if(complete||failure){r.status=complete?'won':'lost';r.finished=sim.tick;r.stars=complete?(r.grant-r.spent>=100?3:2):0;g.medals[r.id]=Math.max(g.medals[r.id]||0,r.stars);if(m.id==='storm')sim.catalyst('Clear');sim.event(complete?`${m.title} complete! Earned ${r.stars} stars.`:`${m.title} ended. Your city continues; try a different approach.`)}}
export function freePlay(sim,mode){const g=gameState(sim);if(g.run?.status==='active'&&g.run.id==='storm')sim.catalyst('Clear');g.run=null;g.mode=mode;g.visited=true;return {ok:true,message:mode==='chaos'?'Chaos Lab: experiment freely. Citizens remain autonomous.':'City Stories: enjoy your city at your own pace.'}}
